referenceSolutions.javascript:
export function solve(input) {
  const d = input;
  const equal = (a, b) => {
    if (a === b) return true;
    if (
      a === null ||
      b === null ||
      typeof a !== "object" ||
      typeof b !== "object" ||
      Array.isArray(a) !== Array.isArray(b)
    )
      return false;
    const keys = Object.keys(a);
    return (
      keys.length === Object.keys(b).length &&
      keys.every((k) => Object.hasOwn(b, k) && equal(a[k], b[k]))
    );
  };
  return d.map((a) => (a.op === "truthy" ? Boolean(a.actual) : equal(a.actual, a.expected)));
}

